<?php
 namespace OSS\Model; use OSS\Core\OssException; class VersioningConfig implements XmlConfig { public function __construct($status = null) { $this->status = $status; } public function parseFromXml($strXml) { $xml = simplexml_load_string($strXml); if (isset($xml->Status)) { $this->status = strval($xml->Status); } } public function serializeToXml() { $xml = new \SimpleXMLElement('<?xml version="1.0" encoding="utf-8"?><VersioningConfiguration></VersioningConfiguration>'); if (isset($this->status)) { $xml->addChild('Status', $this->status); } return $xml->asXML(); } public function __toString() { return $this->serializeToXml(); } public function getStatus() { return $this->status; } private $status = ""; }